arguments.command:
ssh -o BatchMode=yes mm@docker-host 'sudo -n python3 - <<"EOF"
import sqlite3
con = sqlite3.connect("file:/var/lib/docker/volumes/jellyfin-data/_data/data/jellyfin.db?mode=ro", uri=True)
rows = con.execute("SELECT name FROM sqlite_master WHERE type=\"table\" ORDER BY name").fetchall()
for (name,) in rows:
    if any(k in name.lower() for k in ("activ", "playback", "session", "user")):
        try:
            n = con.execute(f"SELECT COUNT(*) FROM \"{name}\"").fetchone()[0]
        except Exception as e:
            n = f"err {e}"
        print(name, n)
print("--- all tables:", " ".join(r[0] for r in rows))
EOF'
